    #[test]
    fn advisory_release_freezes_owner_and_late_readback_failure_rolls_back() {
        let conn = account_conn();
        let bound = bound_advisory_owner_fixture(&conn);
        let token = AdvisoryOwnerPersistenceContext::for_test();
        let owner_view = bound.control_view(token);
        let previous = owner_view.4.clone();
        let owner_id = owner_view.1;
        let (prepared, changed) = prepare_advisory_release_conn(&conn, &bound).unwrap();
        assert!(changed);

        let renewed = previous.renewed_maintenance_lease_for_test();
        let renewed_lease = renewed
            .exact_advisory_owner_heartbeat_from(&previous, owner_id.as_bytes())
            .unwrap();
        assert!(
            persist_advisory_owner_successor_conn(&conn, &previous, &renewed, renewed_lease,)
                .is_err()
        );
        assert_eq!(
            load_bound_advisory_owner_conn(&conn, owner_view.0, &previous)
                .unwrap()
                .control_view(token),
            bound.control_view(token)
        );

        let marker_name = crate::store::test_identity_rebind_fence_object_name(USER_ID);
        let authority = advisory_fence_authority(&conn);
        let observation = AdvisoryFenceObservation::for_test(
            &prepared,
            &marker_name,
            &authority,
            "kioku-identity-rebind-fence-v1",
            9,
        )
        .unwrap();
        let (delete_started, changed) =
            mark_advisory_fence_delete_started_conn(&conn, &prepared, &observation).unwrap();
        assert!(changed);
        let before = delete_started.control_view(token);
        let absence = AdvisoryFenceAbsence::for_test(&delete_started, &marker_name).unwrap();
        conn.execute_batch(
            "CREATE TRIGGER corrupt_advisory_release_after_release
             AFTER UPDATE ON archive_v3_advisory_releases
             WHEN NEW.stage='released'
             BEGIN
               UPDATE archive_v3_advisory_releases
               SET commitment=x'aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa'
               WHERE archive_id=NEW.archive_id;
             END;",
        )
        .unwrap();
        assert!(mark_advisory_fence_released_conn(&conn, &delete_started, &absence).is_err());
        assert!(
            load_advisory_release_conn(&conn, before.archive_id)
                .unwrap()
                .control_view(token)
                == before
        );

        conn.execute_batch("PRAGMA ignore_check_constraints=ON;")
            .unwrap();
        conn.execute(
            "UPDATE archive_v3_advisory_releases
             SET marker_observation_commitment=zeroblob(32)
             WHERE archive_id=?1",
            [before.archive_id.as_bytes().as_slice()],
        )
        .unwrap();
        conn.execute_batch("PRAGMA ignore_check_constraints=OFF;")
            .unwrap();
        assert!(load_advisory_release_conn(&conn, before.archive_id).is_err());
    }

    #[test]
    fn advisory_owner_reserve_send_bind_and_reopen_are_exact() {
        use crate::archive_v3_witness::InMemoryWitness;

        let conn = account_conn();
        let maintenance = seed_maintenance_advisory_parity(&conn).unwrap();
        let release_provider = InMemoryWitness::from_provider_record_at_tick(
            Some(maintenance.shadow.encode()),
            maintenance.shadow.last_server_tick() + 1,
        )
        .unwrap();
        let released = release_provider
            .release_exact_maintenance_advisory(&maintenance.shadow, maintenance.owner_id)
            .unwrap();
        assert!(released.is_exact_unleased_advisory_terminal());

        let (reserved, changed) =
            reserve_advisory_owner_conn(&conn, maintenance.operation_id, &released).unwrap();
        assert!(changed);
        let (replayed, changed) =
            reserve_advisory_owner_conn(&conn, maintenance.operation_id, &released).unwrap();
        assert!(!changed);
        assert_eq!(
            replayed.control_view(AdvisoryOwnerPersistenceContext::for_test()),
            reserved.control_view(AdvisoryOwnerPersistenceContext::for_test())
        );

        let (send_started, changed) =
            mark_advisory_owner_send_started_conn(&conn, &reserved).unwrap();
        assert!(changed);
        let (replayed_send, changed) =
            mark_advisory_owner_send_started_conn(&conn, &send_started).unwrap();
        assert!(!changed);
        assert_eq!(
            replayed_send.control_view(AdvisoryOwnerPersistenceContext::for_test()),
            send_started.control_view(AdvisoryOwnerPersistenceContext::for_test())
        );

        let owner = ObjectId::from_bytes(
            *send_started
                .control_view(AdvisoryOwnerPersistenceContext::for_test())
                .1
                .as_bytes(),
        );
        let acquire_provider = InMemoryWitness::from_provider_record_at_tick(
            Some(released.encode()),
            released.last_server_tick() + 1,
        )
        .unwrap();
        let (observed, lease) = acquire_provider
            .acquire_exact_advisory_owner_lease(&released, owner, 300)
            .unwrap();
        let (bound, changed) =
            bind_advisory_owner_conn(&conn, &send_started, &observed, lease).unwrap();
        assert!(changed);
        assert_eq!(
            bound
                .control_view(AdvisoryOwnerPersistenceContext::for_test())
                .4,
            &observed
        );
        let (replayed_bound, changed) =
            bind_advisory_owner_conn(&conn, &send_started, &observed, lease).unwrap();
        assert!(!changed);
        assert_eq!(
            replayed_bound.control_view(AdvisoryOwnerPersistenceContext::for_test()),
            bound.control_view(AdvisoryOwnerPersistenceContext::for_test())
        );
        assert_eq!(
            load_bound_advisory_owner_conn(&conn, maintenance.operation_id, &observed)
                .unwrap()
                .control_view(AdvisoryOwnerPersistenceContext::for_test()),
            bound.control_view(AdvisoryOwnerPersistenceContext::for_test())
        );

        let renewed = observed.renewed_maintenance_lease_for_test();
        let renewed_lease = renewed
            .exact_advisory_owner_heartbeat_from(&observed, owner.as_bytes())
            .unwrap();
        let (renewed_bound, changed) =
            persist_advisory_owner_successor_conn(&conn, &observed, &renewed, renewed_lease)
                .unwrap();
        assert!(changed);
        let (replayed_renewal, changed) =
            persist_advisory_owner_successor_conn(&conn, &observed, &renewed, renewed_lease)
                .unwrap();
        assert!(!changed);
        assert_eq!(
            replayed_renewal.control_view(AdvisoryOwnerPersistenceContext::for_test()),
            renewed_bound.control_view(AdvisoryOwnerPersistenceContext::for_test())
        );

        let reacquired = renewed.reacquired_maintenance_lease_for_test();
        let reacquired_lease = reacquired
            .exact_advisory_owner_reacquire_from(&renewed, owner.as_bytes())
            .unwrap();
        let (reacquired_bound, changed) =
            persist_advisory_owner_successor_conn(&conn, &renewed, &reacquired, reacquired_lease)
                .unwrap();
        assert!(changed);
        assert_eq!(
            load_retained_advisory_owner_conn(&conn, maintenance.operation_id)
                .unwrap()
                .control_view(AdvisoryOwnerPersistenceContext::for_test()),
            reacquired_bound.control_view(AdvisoryOwnerPersistenceContext::for_test())
        );

        let substituted = reacquired.with_next_fencing_epoch_for_test(
            reacquired.root().root().sequence().saturating_add(10),
        );
        assert!(
            load_bound_advisory_owner_conn(&conn, maintenance.operation_id, &substituted).is_err()
        );
        assert!(reserve_advisory_owner_conn(
            &conn,
            maintenance.operation_id,
            &released.with_migration_for_test(
                crate::archive_v3_witness::MigrationState::WalAuthoritative
            )
        )
        .is_err());
        conn.execute_batch(
            "CREATE TRIGGER corrupt_advisory_owner_successor
             AFTER UPDATE ON archive_v3_advisory_owners
             WHEN NEW.revision=6
             BEGIN
               UPDATE archive_v3_advisory_owners
               SET commitment=zeroblob(32)
               WHERE archive_id=NEW.archive_id;
             END;",
        )
        .unwrap();
        let later = reacquired.renewed_maintenance_lease_for_test();
        let later_lease = later
            .exact_advisory_owner_heartbeat_from(&reacquired, owner.as_bytes())
            .unwrap();
        assert!(
            persist_advisory_owner_successor_conn(&conn, &reacquired, &later, later_lease,)
                .is_err()
        );
        assert_eq!(
            load_retained_advisory_owner_conn(&conn, maintenance.operation_id)
                .unwrap()
                .control_view(AdvisoryOwnerPersistenceContext::for_test()),
            reacquired_bound.control_view(AdvisoryOwnerPersistenceContext::for_test())
        );
        assert_eq!(
            conn.query_row(
                "SELECT count(*) FROM archive_v3_advisory_owners WHERE stage='bound' AND revision=5",
                [],
                |row| row.get::<_, i64>(0),
            )
            .unwrap(),
            1
        );
    }

    #[test]
    fn verified_advisory_canary_issuer_replays_exactly_and_rolls_back_late_corruption() {
        use crate::archive_v3_witness::InMemoryWitness;

        let conn = account_conn();
        let maintenance = seed_maintenance_advisory_parity(&conn).unwrap();
        let release_provider = InMemoryWitness::from_provider_record_at_tick(
            Some(maintenance.shadow.encode()),
            maintenance.shadow.last_server_tick() + 1,
        )
        .unwrap();
        let released = release_provider
            .release_exact_maintenance_advisory(&maintenance.shadow, maintenance.owner_id)
            .unwrap();
        let terminal =
            advisory_canary_terminal_facts_conn(&conn, maintenance.operation_id, &released)
                .unwrap();
        let authorization = VerifiedAdvisoryCanaryAuthorization::for_control_test(
            [0xd0; 16],
            &terminal.user_id,
            terminal.archive_id,
            maintenance.operation_id,
            terminal.operation_commitment,
            terminal.source_commitment,
            terminal.parity_commitment,
            terminal.terminal_witness_hash,
            [0xd1; 32],
            [0xd2; 32],
            [0xd3; 32],
        )
        .unwrap();
        conn.execute_batch(
            "CREATE TRIGGER corrupt_advisory_canary_authorization_after_insert
             AFTER INSERT ON archive_v3_advisory_canary_scopes
             BEGIN
               UPDATE archive_v3_advisory_canary_scopes
               SET operator_statement_commitment=x'd3d3d3d3d3d3d3d3d3d3d3d3d3d3d3d3d3d3d3d3d3d3d3d3d3d3d3d3d3d3d3d3d3'
               WHERE scope_id=NEW.scope_id;
             END;",
        )
        .unwrap();
        assert!(authorize_advisory_canary_conn(&conn, &authorization, &released).is_err());
        assert_eq!(
            conn.query_row(
                "SELECT count(*) FROM archive_v3_advisory_canary_scopes",
                [],
                |row| row.get::<_, i64>(0),
            )
            .unwrap(),
            0,
            "late issuer readback corruption must roll back the scope row"
        );
        conn.execute_batch(
            "DROP TRIGGER corrupt_advisory_canary_authorization_after_insert;
             CREATE TRIGGER corrupt_advisory_activation_authorization_after_insert
             AFTER INSERT ON archive_v3_advisory_activation_preconditions
             BEGIN
               UPDATE archive_v3_advisory_activation_preconditions
               SET monitoring_policy_commitment=x'd4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4'
               WHERE scope_id=NEW.scope_id;
             END;",
        )
        .unwrap();
        assert!(authorize_advisory_canary_conn(&conn, &authorization, &released).is_err());
        assert_eq!(
            conn.query_row(
                "SELECT count(*) FROM archive_v3_advisory_canary_scopes",
                [],
                |row| row.get::<_, i64>(0),
            )
            .unwrap(),
            0,
            "late precondition readback corruption must roll back both authorization rows"
        );
        conn.execute_batch("DROP TRIGGER corrupt_advisory_activation_authorization_after_insert;")
            .unwrap();
        let (issued, changed) =
            authorize_advisory_canary_conn(&conn, &authorization, &released).unwrap();
        assert!(changed);
        let (replayed, changed) =
            authorize_advisory_canary_conn(&conn, &authorization, &released).unwrap();
        assert!(!changed);
        assert_eq!(
            replayed.control_view(AdvisoryOwnerPersistenceContext::for_test()),
            issued.control_view(AdvisoryOwnerPersistenceContext::for_test())
        );
        let conflicting = VerifiedAdvisoryCanaryAuthorization::for_control_test(
            [0xd4; 16],
            &terminal.user_id,
            terminal.archive_id,
            maintenance.operation_id,
            terminal.operation_commitment,
            terminal.source_commitment,
            terminal.parity_commitment,
            terminal.terminal_witness_hash,
            [0xd1; 32],
            [0xd2; 32],
            [0xd3; 32],
        )
        .unwrap();
        assert!(authorize_advisory_canary_conn(&conn, &conflicting, &released).is_err());
    }

